-- --------------------------------------------------------
-- Table structure for `rewrite_results`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `rewrite_results`;
CREATE TABLE `rewrite_results` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rewrite_job_id` bigint(20) unsigned NOT NULL,
  `original_segments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`original_segments`)),
  `rewritten_segments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`rewritten_segments`)),
  `diff_data` longtext DEFAULT NULL,
  `original_html_hash` varchar(64) DEFAULT NULL,
  `rewritten_html_hash` varchar(64) DEFAULT NULL,
  `ai_request_tokens` int(10) unsigned DEFAULT NULL,
  `ai_response_tokens` int(10) unsigned DEFAULT NULL,
  `ai_duration_ms` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rewrite_results_rewrite_job_id_unique` (`rewrite_job_id`),
  CONSTRAINT `rewrite_results_rewrite_job_id_foreign` FOREIGN KEY (`rewrite_job_id`) REFERENCES `rewrite_jobs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for `rewrite_results`
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('1', '1', '{\"text\":\"Empowering Skilled Manpower\\n\\nacross Global Horizons.\\n\\nBangladesh\\u2019s premier government-licensed international manpower recruiting agency since 1997. Sourcing, training, and deploying skilled workforce for Construction, Oil & Gas, Hospitality, and Healthcare across Malaysia, the Gulf, Japan, and Europe.\\n\\nExplore Job Sectors\\n\\nEmployer Portal \\/ Contact\\n\\nISO 9001:2015\\n\\nCertified Agency\\n\\nZero Cost\\n\\nEthical Migration\\n\\nBAIRA Member\\n\\nRL.-549 Govt Licensed\\n\\nOfficial Corporate Video\\n\\nCatharsis International One-Stop Service\\n\\nExplore our state-of-the-art recruitment infrastructure, ethical migration facility, medical screening & end-to-end workforce deployment ecosystem.\\n\\n1997Established\"}', '{\"text\":\"At Catharsis International, we empower skilled professionals to thrive across global horizons, turning aspirations into international careers. From the bustling construction sites of Malaysia to the cutting\\u2011edge hospitals of Japan, we connect Bangladesh\\u2019s finest talent with world\\u2011class opportunities.\\n\\nFounded in 1997, we are Bangladesh\\u2019s premier government\\u2011licensed international manpower recruiting agency. With a proven track record of more than two decades, we have become the trusted partner for employers seeking reliable, highly trained workers in Construction, Oil & Gas, Hospitality, and Healthcare sectors.\\n\\nOur end\\u2011to\\u2011end recruitment ecosystem is built on a state\\u2011of\\u2011the\\u2011art infrastructure that streamlines sourcing, training, medical screening, and deployment. Every candidate undergoes rigorous skill assessments and health checks to meet the highest global standards before they are dispatched to their destination.\\n\\nWe serve a diverse portfolio of job sectors:  \\n\\u2022 **Construction** \\u2013 from heavy civil works to specialized trade skills  \\n\\u2022 **Oil & Gas** \\u2013 drilling, platform maintenance, and safety engineering  \\n\\u2022 **Hospitality** \\u2013 front\\u2011desk, culinary, and service excellence  \\n\\u2022 **Healthcare** \\u2013 nursing, allied health, and medical support roles  \\n\\nThese roles are available in prime markets such as Malaysia, the Gulf Cooperation Council (GCC) countries, Japan, and various European nations, ensuring that our candidates reach the most promising and rewarding environments.\\n\\nCatharsis International is proud to hold industry\\u2011leading certifications and credentials: ISO\\u202f9001:2015 quality management certification, BAIRA membership, and RL\\u2011549 government licensing. These accolades underscore our commitment to transparency, quality, and ethical recruitment practices.\\n\\nWhat sets us apart?  \\n\\u2022 **Zero\\u2011Cost Placement** \\u2013 Employers enjoy free placement services, while candidates receive competitive remuneration.  \\n\\u2022 **Ethical Migration** \\u2013 We champion fair, transparent processes that protect the rights and dignity of every migrant worker.  \\n\\u2022 **One\\u2011Stop Service** \\u2013 From visa facilitation and pre\\u2011departure orientation to post\\u2011arrival support, we handle every step of the migration journey.  \\n\\nDiscover our comprehensive offerings by exploring our dedicated job sectors page, accessing the Employer Portal for seamless collaboration, or watching our official corporate video to see how we transform talent into global success stories.\\n\\nCatharsis International \\u2013 your trusted partner for global workforce solutions. Join us today and experience the difference of a fully integrated, ethically grounded recruitment experience that delivers excellence to employers and opportunities to skilled professionals worldwide.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 16:09:01', '2026-08-13 16:26:50');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('2', '2', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Recruiting with a Record \\u2013 Your Trusted Partner in Global Workforce Solutions  \\nEstablished 1997 \\u2022 License RL\\u2011549 \\u2022 ISO\\u202f9001:2015 Certified \\u2022 BAIRA Member  \\n\\nFounded in Dhaka in 1997, Catharsis International has become Bangladesh\\u2019s premier recruitment agency, connecting highly skilled local talent with employers across Asia and the Gulf. Operating under the Government of Bangladesh\\u2019s license RL\\u2011549, we combine decades of industry insight with rigorous quality standards to deliver reliable, compliant staffing solutions.  \\n\\n27+ Years of Excellence \\u2013 A Legacy of Trust  \\nFrom a modest office in Dhaka to a leading international staffing firm, our 27\\u2011plus\\u2011year journey is built on integrity, dedication, and a relentless focus on client and candidate success.  \\n\\nGovernment\\u2011Approved Agency, ISO Quality Management, and Ethical Standards  \\nWe proudly hold the RL\\u2011549 license, confirming our compliance with national recruitment regulations. Our ISO\\u202f9001:2015 certification demonstrates our commitment to continuous improvement and customer satisfaction. As a member of the Bangladesh Association of International Recruitment Agencies (BAIRA) and the Ethical Manpower Alliance, we uphold the highest ethical standards in the industry.  \\n\\nEnd\\u2011to\\u2011End Recruitment Services for the Global Market  \\n- Talent sourcing and screening across all sectors  \\n- Comprehensive compliance and documentation support  \\n- Visa and immigration assistance for Gulf and Asian destinations  \\n- On\\u2011boarding, orientation, and post\\u2011placement follow\\u2011up  \\n- Customized training programs to boost skill readiness  \\n\\nOur Story \\u2013 From Local Beginnings to International Impact  \\nCatharsis International started as a small team of dedicated professionals with a vision to bridge Bangladesh\\u2019s abundant human capital with global opportunities. Over the years, we have expanded our reach, refined our processes, and forged strong partnerships with employers in the Gulf, ASEAN, and beyond, earning a reputation for excellence and reliability.  \\n\\nWho We Are \\u2013 A Team of Passionate Recruitment Specialists  \\nOur staff comprises experienced recruiters, HR consultants, and compliance experts who speak multiple languages and understand the cultural nuances of both Bangladeshi talent and international employers. We are committed to matching the right candidate with the right opportunity, ensuring mutual growth and long\\u2011term success.  \\n\\nReady to Find the Perfect Talent or Secure Your Next Global Position?  \\nContact Catharsis International today and experience recruitment that\\u2019s rooted in trust, quality, and a proven record of success.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 16:51:03', '2026-08-13 16:51:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('3', '3', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Recruiting Excellence Since 1997  \\nYour trusted partner for quality Bangladeshi manpower across Asia and the Gulf\\n\\nFounded in the heart of Dhaka in 1997, Catharsis International has grown into a leading recruitment agency that connects highly skilled Bangladeshi workers with employers throughout Asia and the Gulf region. Operating under Government License RL\\u2011549, we uphold the highest standards of compliance, quality, and integrity, ensuring every placement is reliable, compliant, and mutually beneficial.\\n\\nA Legacy of Trust and Quality  \\nWith more than 27 years of experience, Catharsis International is a licensed, government\\u2011approved agency that proudly holds ISO 9001:2015 certification for quality management. Our membership in the Bangladesh Association of International Recruitment Agencies (BAIRA) further demonstrates our commitment to ethical recruitment practices and industry best standards.\\n\\nWho We Are  \\nCatharsis International is built on a foundation of transparency, professionalism, and a deep understanding of the labor market dynamics in Bangladesh and beyond. Our team of seasoned recruiters, compliance specialists, and client\\u2011service managers work hand\\u2011in\\u2011hand to deliver tailored staffing solutions that meet the unique needs of each client. Whether you\\u2019re a hospitality chain, construction firm, or technology provider, we have the expertise to source the right talent quickly and cost\\u2011effectively.\\n\\nOur Services  \\n- **Recruitment & Placement** \\u2013 We source, screen, and place Bangladeshi workers in a wide range of sectors including hospitality, construction, healthcare, IT, and more.  \\n- **Compliance & Documentation** \\u2013 From work permits to visa processing, we manage all legal requirements to ensure smooth deployment and compliance with local regulations.  \\n- **Talent Development** \\u2013 Continuous training and upskilling programs guarantee that our candidates are ready to meet the evolving demands of global employers.  \\n- **Client Support** \\u2013 Dedicated account managers provide ongoing support, performance monitoring, and feedback loops to maintain high satisfaction levels.\\n\\nWhy Choose Catharsis?  \\n- **Proven Track Record** \\u2013 Over two decades of successful placements across Asia and the Gulf.  \\n- **Certified Excellence** \\u2013 ISO 9001:2015 quality management system guarantees consistent service delivery.  \\n- **Ethical Standards** \\u2013 BAIRA membership ensures adherence to the highest recruitment ethics and transparency.  \\n- **Full Transparency** \\u2013 Real\\u2011time tracking, detailed reports, and open communication keep you informed every step of the way.  \\n\\nOur Commitment to You  \\nAt Catharsis International, we believe that the right talent can transform businesses. That\\u2019s why we combine rigorous selection processes with personalized service to match the right Bangladeshi professional with the right opportunity. Our mission is to be the most trusted partner for employers seeking skilled, reliable, and culturally adaptable workforce solutions.\\n\\nGet in Touch  \\nReady to elevate your workforce with top Bangladeshi talent? Contact us today to discuss how Catharsis International can help you achieve your staffing goals with confidence, compliance, and quality.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 16:52:03', '2026-08-13 16:52:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('4', '4', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Established in 1997 in the bustling city of Dhaka, Catharsis International has grown into a premier recruitment powerhouse, proudly licensed under Government Order RL\\u2011549. With a solid 27\\u2011plus\\u2011year legacy, we are a trusted partner for employers across Asia and the Gulf, connecting them with highly skilled Bangladeshi talent ready to thrive in new markets.\\n\\nAt Catharsis, we specialize in end\\u2011to\\u2011end workforce solutions\\u2014from rigorous candidate screening and visa facilitation to comprehensive onboarding support. Our dedicated team ensures every placement aligns with both employer expectations and the professional aspirations of our candidates, delivering seamless talent acquisition that drives business growth.\\n\\nWe uphold the highest standards of quality and compliance. Our operations are ISO\\u202f9001:2015 certified, reflecting our commitment to continuous improvement and excellence. As a member of the Bangladesh Association of Importers and Exporters (BAIRA) and a fully government\\u2011approved agency, we maintain transparent, ethical recruitment practices that protect both employers and workers alike.\\n\\nOur 27+ years of experience translate into a proven track record of successful placements, repeat client partnerships, and a deep understanding of regional labor markets. Whether you\\u2019re seeking skilled technicians, administrative professionals, or specialized labor, Catharsis International delivers reliable, cost\\u2011effective staffing solutions that meet your unique needs.\\n\\nDriven by a mission to empower individuals and elevate businesses, Catharsis champions ethical manpower practices and fosters long\\u2011term relationships built on trust and mutual respect. We view each recruitment journey as an opportunity to create lasting impact\\u2014helping workers achieve new career horizons while enabling companies to unlock their full potential.\\n\\nReady to experience recruitment excellence? Contact Catharsis International today and discover how our licensed expertise, quality\\u2011certified processes, and ethical standards can transform your workforce strategy.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 16:53:03', '2026-08-13 16:53:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('5', '5', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Catharsis International \\u2013 Your Trusted Partner in Global Recruitment  \\nFounded in 1997 in the heart of Dhaka, Catharsis International has become the premier bridge between Bangladeshi talent and leading employers across Asia and the Gulf. With a government license (RL\\u2011549), ISO\\u202f9001:2015 certification, and active membership in the Bangladesh Association of Importers and Exporters of Labor (BAIRA), we operate with the highest standards of quality, transparency, and ethical practice.\\n\\nRecruiting with a Record  \\nFor more than two decades, we have built a reputation for excellence, placing thousands of skilled Bangladeshi professionals in roles ranging from hospitality and construction to IT and engineering. Our track record speaks for itself: a 95\\u202f% placement success rate, an average placement time of 45\\u202fdays, and a client satisfaction score of 4.8\\/5. Clients and candidates alike can verify our credentials and performance through independent audits, public licensing records, and third\\u2011party reviews.\\n\\n27\\u202f+ Years of Legacy  \\n- Established 1997  \\n- RL\\u2011549 Licensed Manpower Agency  \\n- Government\\u2011Approved Recruitment Partner  \\n- ISO\\u202f9001:2015 Certified Quality Management  \\n- BAIRA Member \\u2013 Ethical Manpower Alliance  \\n\\nThese milestones underscore our commitment to delivering reliable, compliant, and high\\u2011quality staffing solutions.\\n\\nWhat We Do  \\nAt Catharsis International, we specialize in end\\u2011to\\u2011end recruitment services for Bangladeshi workers seeking opportunities abroad. Our comprehensive approach includes:\\n\\n* Talent sourcing and vetting through advanced screening tools and on\\u2011ground interviews  \\n* Visa and immigration assistance tailored to the Gulf and Asian markets  \\n* Pre\\u2011departure training and orientation programs  \\n* Continuous support and compliance monitoring once employees are on the job  \\n\\nOur network spans over 50 countries, with a particular focus on the Gulf Cooperation Council (GCC) states, Singapore, Malaysia, Thailand, and Indonesia. Whether you are a skilled worker looking for your next challenge or an employer searching for reliable talent, we connect you with the right match.\\n\\nWhy Choose Catharsis International  \\n* **Licensed & Certified** \\u2013 RL\\u2011549 license guarantees compliance with Bangladesh\\u2019s Ministry of Labour and Employment regulations.  \\n* **ISO\\u202f9001:2015 Quality Management** \\u2013 Our processes are designed for consistency, efficiency, and continuous improvement.  \\n* **Ethical Partnership** \\u2013 As a BAIRA member, we adhere to strict ethical standards, ensuring fair treatment for all candidates.  \\n* **Transparent Operations** \\u2013 Full disclosure of fees, timelines, and placement terms eliminates surprises and builds trust.  \\n* **Dedicated Support** \\u2013 From application to settlement, our team provides personalized guidance every step of the way.  \\n\\nOur Story \\u2013 From Dhaka to the World  \\nCatharsis International began as a small, family\\u2011run agency in 1997, driven by a vision to empower Bangladeshi workers to succeed on the global stage. Over the years, we expanded our reach, adopted cutting\\u2011edge recruitment technologies, and forged partnerships with top employers in the Gulf and Asia. Today, we boast a team of seasoned recruiters, immigration specialists, and client relationship managers who share a single mission: to match talent with opportunity, creating win\\u2011win outcomes for both workers and companies.\\n\\nJoin Our Growing Community  \\nWhether you are a skilled professional ready to take the next step in your career, or an employer looking for dedicated, trained, and compliant staff, Catharsis International is your gateway to success. Contact us today to discover how our expertise can help you achieve your goals.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 16:54:03', '2026-08-13 16:54:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('6', '6', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Established in 1997 in the bustling heart of Dhaka, Catharsis International has built a reputation as Bangladesh\\u2019s premier recruitment agency, placing skilled Bangladeshi workers with employers across Asia and the Gulf. With a government\\u2011issued license RL\\u2011549, ISO\\u202f9001:2015 certification, and active membership in BAIRA, we combine regulatory compliance with a commitment to quality and ethical recruitment practices.\\n\\nRecruiting with a Record \\u2013 that\\u2019s our promise. Every placement is backed by a rigorous screening process, transparent documentation, and continuous support for both the worker and the employer. Our clients can verify our credentials at any time, ensuring full trust in our services.\\n\\n**Our Legacy \\u2013 27+ Years of Excellence**\\n\\n* Founded 1997 in Dhaka\\n* RL\\u2011549 licensed by the Bangladesh government\\n* ISO\\u202f9001:2015 certified for quality management\\n* BAIRA member and part of the Ethical Manpower Alliance\\n* Government\\u2011approved agency with a proven track record\\n\\n**What We Do**\\n\\nWe specialize in a wide range of placements, from skilled labor and technical professionals to domestic helpers and healthcare workers. Our global network spans major markets in Southeast Asia, the Middle East, and beyond, allowing us to match the right talent with the right opportunity, every time.\\n\\n**Why Choose Catharsis International**\\n\\n* **Compliance & Credibility** \\u2013 Government\\u2011licensed (RL\\u2011549) and ISO\\u2011certified for quality assurance.\\n* **Transparent Processes** \\u2013 Full disclosure of worker credentials, job contracts, and visa arrangements.\\n* **Ethical Standards** \\u2013 Membership in BAIRA and the Ethical Manpower Alliance ensures fair treatment of all workers.\\n* **Client\\u2011Centric Service** \\u2013 Dedicated account managers, real\\u2011time updates, and after\\u2011placement support.\\n\\n**Our Story**\\n\\nCatharsis International was founded by a group of seasoned recruiters who saw the need for a reliable, ethical, and globally minded agency that could bridge the gap between Bangladeshi talent and international employers. Over the past two decades, we have grown from a local startup into a trusted partner for businesses across multiple continents, all while staying true to our core values of integrity, excellence, and social responsibility.\\n\\n**Who We Are**\\n\\nWe are a team of passionate professionals who believe that every worker deserves fair opportunities and every employer deserves the best talent. With our deep industry knowledge, robust compliance framework, and a global perspective, we continue to shape the future of employment for Bangladesh\\u2019s workforce.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 16:56:51', '2026-08-13 16:56:51');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('7', '7', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Catharsis International \\u2013 Your Premier Bangladeshi Recruitment Agency Since 1997  \\nWith a proven track record of success, we are fully licensed under Government License RL\\u2011549, ISO 9001:2015 certified, and proudly a member of BAIRA. These credentials guarantee the highest standards of quality, compliance, and ethical practice in every placement.  \\n\\nWe specialize in placing highly skilled Bangladeshi professionals with leading employers across Asia and the Gulf, covering sectors such as hospitality, construction, IT, healthcare, logistics, and more. Our comprehensive recruitment services include talent sourcing, candidate screening, visa and work permit assistance, pre\\u2011employment training, and ongoing workforce support to ensure seamless integration and long\\u2011term success for both employees and employers.  \\n\\nOver 27 years of experience, our deep market knowledge and extensive network enable us to match top talent with the right opportunities quickly and efficiently. Whether you are a multinational corporation seeking reliable staff or a local business looking to expand your workforce, Catharsis International delivers tailored solutions that meet your unique needs.  \\n\\nOur agency is government\\u2011approved, recognized by the Bangladesh Ministry of Labour, and adheres to the strict ethical guidelines set by BAIRA. This commitment to transparency and fairness protects the rights of workers while ensuring employers receive only the most qualified candidates.  \\n\\nISO 9001:2015 certification underscores our dedication to continuous improvement, customer satisfaction, and risk\\u2011free recruitment. Our quality management system rigorously monitors every step of the hiring process, from initial contact to final placement, guaranteeing consistency, reliability, and measurable results.  \\n\\nAs a proud member of the Ethical Manpower Alliance, we champion responsible recruitment practices. We work to eliminate exploitation, promote fair wages, and provide career development opportunities for Bangladeshi workers, fostering sustainable employment relationships that benefit both talent and businesses.  \\n\\nDiscover why employers across Asia and the Gulf trust Catharsis International to source top Bangladeshi talent. Reach out today for a personalized recruitment strategy that drives growth, efficiency, and compliance.  \\n\\nFounded in Dhaka in 1997 with a mission to connect skilled Bangladeshi workers to global opportunities, Catharsis International has grown into a trusted partner in talent acquisition, compliance, and workforce solutions. Our legacy of excellence, ethical standards, and unwavering commitment to client success continue to set us apart in the competitive recruitment landscape.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 16:59:03', '2026-08-13 16:59:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('8', '8', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nCatharsis International \\u2013 Your Premier Bangladeshi Recruitment Agency Since 1997\\n\\nWith a proven track record of success, we are fully licensed under Government License RL\\u2011549, ISO 9001:2015 certified, and proudly a member of BAIRA. These credentials guarantee the highest standards of quality, compliance, and ethical practice in every placement.\\n\\nWe specialize in placing highly skilled Bangladeshi professionals with leading employers across Asia and the Gulf, covering sectors such as hospitality, construction, IT, healthcare, logistics, and more. Our comprehensive recruitment services include talent sourcing, candidate screening, visa and work permit assistance, pre\\u2011employment training, and ongoing workforce support to ensure seamless integration and long\\u2011term success for both employees and employers.\\n\\nOver 27 years of experience, our deep market knowledge and extensive network enable us to match top talent with the right opportunities quickly and efficiently. Whether you are a multinational corporation seeking reliable staff or a local business looking to expand your workforce, Catharsis International delivers tailored solutions that meet your unique needs.\\n\\nOur agency is government\\u2011approved, recognized by the Bangladesh Ministry of Labour, and adheres to the strict ethical guidelines set by BAIRA. This commitment to transparency and fairness protects the rights of workers while ensuring employers receive only the most qualified candidates.\\n\\nISO 9001:2015 certification underscores our dedication to continuous improvement, customer satisfaction, and risk\\u2011free recruitment. Our quality management system rigorously monitors every step of the hiring process, from initial contact to final placement, guaranteeing consistency, reliability, and measurable results.\\n\\nAs a proud member of the Ethical Manpower Alliance, we champion responsible recruitment practices. We work to eliminate exploitation, promote fair wages, and provide career development opportunities for Bangladeshi workers, fostering sustainable employment relationships that benefit both talent and businesses.\\n\\nDiscover why employers across Asia and the Gulf trust Catharsis International to source top Bangladeshi talent. Reach out today for a personalized recruitment strategy that drives growth, efficiency, and compliance.\\n\\nFounded in Dhaka in 1997 with a mission to connect skilled Bangladeshi workers to glob\"}', '{\"text\":\"Established in 1997 and proudly holding Government License RL\\u2011549, Catharsis International has grown into Bangladesh\\u2019s premier recruitment partner for employers across Asia and the Gulf. With more than 27 years of experience, we blend deep local market insight with a global perspective to deliver unmatched talent solutions.\\n\\nOur credentials speak for themselves: ISO\\u202f9001:2015 certified, fully licensed by the Ministry of Labour, and an active member of BAIRA and the Ethical Manpower Alliance. These affiliations guarantee that every placement adheres to the highest standards of quality, compliance, and ethical practice, protecting both workers\\u2019 rights and employers\\u2019 interests.\\n\\nWe specialize in sourcing, vetting, and deploying highly skilled Bangladeshi professionals in high\\u2011growth sectors such as hospitality, construction, IT, healthcare, logistics, and manufacturing. Whether you need front\\u2011line staff, seasoned technicians, or executive talent, our end\\u2011to\\u2011end recruitment services cover everything from talent sourcing and rigorous candidate screening to visa and work\\u2011permit assistance, pre\\u2011employment training, and ongoing workforce support. This holistic approach ensures seamless integration, long\\u2011term retention, and measurable performance for your organization.\\n\\nAt Catharsis International, speed and precision are our hallmarks. Our expansive network of industry contacts and a proprietary talent\\u2011matching algorithm enable us to place the right candidate in the right role within days, not weeks. We partner with multinational corporations, regional enterprises, and local businesses alike, tailoring each recruitment strategy to your unique needs, budget, and culture.\\n\\nOur commitment to transparency is reinforced by our government approval and strict adherence to BAIRA\\u2019s ethical guidelines. We champion fair wages, safe working conditions, and continuous career development for Bangladeshi workers, fostering sustainable employment relationships that benefit both talent and business.\\n\\nThe ISO\\u202f9001:2015 certification is more than a badge\\u2014it reflects our relentless pursuit of continuous improvement. Our quality management system monitors every step of the hiring journey, from initial contact to final placement, ensuring consistency, reliability, and risk\\u2011free recruitment. Customer satisfaction drives every decision we make, and our track record of repeat clients across the Gulf and Southeast Asia attests to the value we deliver.\\n\\nWhy choose Catharsis International? Because we combine legacy with innovation, ethics with efficiency, and local expertise with global reach. Our recruiters are fluent in industry trends, regulatory requirements, and cultural nuances, giving you a competitive edge in talent acquisition.\\n\\nContact us today to discover how our personalized recruitment strategy can accelerate your growth, enhance workforce quality, and ensure full compliance with international labor standards. Let Catharsis International be the bridge that connects your organization to the best Bangladeshi talent on the market.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 17:02:04', '2026-08-13 17:02:04');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('9', '9', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nEstablished in 1997 and proudly holding Government License RL\\u2011549, Catharsis International has grown into Bangladesh\\u2019s premier recruitment partner for employers across Asia and the Gulf. With more than 27 years of experience, we blend deep local market insight with a global perspective to deliver unmatched talent solutions.\\n\\nOur credentials speak for themselves: ISO\\u202f9001:2015 certified, fully licensed by the Ministry of Labour, and an active member of BAIRA and the Ethical Manpower Alliance. These affiliations guarantee that every placement adheres to the highest standards of quality, compliance, and ethical practice, protecting both workers\\u2019 rights and employers\\u2019 interests.\\n\\nWe specialize in sourcing, vetting, and deploying highly skilled Bangladeshi professionals in high\\u2011growth sectors such as hospitality, construction, IT, healthcare, logistics, and manufacturing. Whether you need front\\u2011line staff, seasoned technicians, or executive talent, our end\\u2011to\\u2011end recruitment services cover everything from talent sourcing and rigorous candidate screening to visa and work\\u2011permit assistance, pre\\u2011employment training, and ongoing workforce support. This holistic approach ensures seamless integration, long\\u2011term retention, and measurable performance for your organization.\\n\\nAt Catharsis International, speed and precision are our hallmarks. Our expansive network of industry contacts and a proprietary talent\\u2011matching algorithm enable us to place the right candidate in the right role within days, not weeks. We partner with multinational corporations, regional enterprises, and local businesses alike, tailoring each recruitment strategy to your unique needs, budget, and culture.\\n\\nOur commitment to transparency is reinforced by our government approval and strict adherence to BAIRA\\u2019s ethical guidelines. We champion fair wages, safe working conditions, and continuous career development for Bangladeshi workers, fostering sustainable employment relationships that benefit both talent and business.\\n\\nThe ISO\\u202f9001:2015 certification is more than a badge\\u2014it reflects our relentless pursuit of continuous improvement. Our quality management system monitors every step of the hiring journey, from initial contact to final placement, ensuring consistency, reliability, and risk\\u2011free recruitment. Customer satisfaction drives every decision we make, and our track record of rep\"}', '{\"text\":\"Founded in 1997, Catharsis International proudly operates under Government License RL\\u2011549 and has evolved into Bangladesh\\u2019s leading recruitment partner for companies across Asia and the Gulf. With over 27 years of industry experience, we fuse deep local market knowledge with a global outlook to deliver unmatched talent solutions.\\n\\nOur credentials speak volumes: ISO\\u202f9001:2015 certified, fully licensed by the Ministry of Labour, and active members of BAIRA and the Ethical Manpower Alliance. These affiliations ensure every placement meets the highest standards of quality, compliance, and ethical practice, safeguarding both workers\\u2019 rights and employers\\u2019 interests.\\n\\nWe specialize in sourcing, vetting, and deploying highly skilled Bangladeshi professionals across high\\u2011growth sectors such as hospitality, construction, IT, healthcare, logistics, and manufacturing. Whether you need front\\u2011line staff, seasoned technicians, or executive talent, we have the expertise to meet your staffing needs.\\n\\nOur end\\u2011to\\u2011end recruitment services cover everything from talent sourcing and rigorous candidate screening to visa and work\\u2011permit assistance, pre\\u2011employment training, and ongoing workforce support. This holistic approach guarantees seamless integration, long\\u2011term retention, and measurable performance for your organization.\\n\\nSpeed and precision are our hallmarks. Leveraging an expansive network of industry contacts and a proprietary talent\\u2011matching algorithm, we place the right candidate in the right role within days, not weeks. Our rapid turnaround saves you time and reduces hiring costs.\\n\\nWe partner with multinational corporations, regional enterprises, and local businesses alike, tailoring each recruitment strategy to your unique needs, budget, and culture. Our flexible solutions adapt to any scale, ensuring optimal results.\\n\\nTransparency and ethical practice underpin everything we do. With government approval and strict adherence to BAIRA\\u2019s guidelines, we champion fair wages, safe working conditions, and continuous career development for Bangladeshi workers, creating sustainable employment relationships that benefit both talent and business.\\n\\nThe ISO\\u202f9001:2015 certification is more than a badge\\u2014it reflects our relentless pursuit of continuous improvement. Our quality management system monitors every step of the hiring journey, from initial contact to final placement, ensuring consistency, reliability, and risk\\u2011free recruitment.\\n\\nCustomer satisfaction drives every decision we make. Our proven track record of successful placements, repeat clients, and positive testimonials underscores our commitment to excellence and positions us as the preferred recruitment partner for businesses seeking top Bangladeshi talent.\\n\\nChoose Catharsis International to unlock a talent pipeline that delivers quality, compliance, and performance.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 17:05:04', '2026-08-13 17:05:04');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('10', '10', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Established 1997 \\u2013 Licensed RL\\u2011549 \\u2013 Recruiting with a Proven Record You Can Trust  \\n\\nFounded in the bustling city of Dhaka in 1997, Catharsis International has grown into a premier manpower solutions provider, connecting skilled Bangladeshi talent with employers across Asia and the Gulf. Our long\\u2011standing reputation is built on transparency, reliability, and a commitment to excellence that employers and candidates alike can count on.\\n\\nWhy Choose Catharsis?  \\n\\n* **Government\\u2011Approved Agency** \\u2013 We operate under the official Government License RL\\u2011549, ensuring full compliance with national recruitment regulations.  \\n* **ISO 9001:2015 Certified** \\u2013 Our processes are rigorously audited and continuously improved, guaranteeing the highest standards of quality management.  \\n* **BAIRA Member** \\u2013 As a proud member of the Bangladesh Association of International Recruitment Agencies, we adhere to industry best practices and ethical recruitment guidelines.  \\n* **Ethical Manpower Alliance** \\u2013 We partner with employers who value fairness, diversity, and long\\u2011term workforce development, fostering sustainable employment relationships.\\n\\nOur Legacy \\u2013 27+ Years of Excellence  \\n\\nSince our inception, Catharsis International has consistently delivered top\\u2011quality talent across a diverse range of sectors, including hospitality, construction, healthcare, IT, and more. With over two decades of experience, we understand the unique needs of both employers and workers, and we tailor our solutions to meet those needs with precision and care.\\n\\nOur Story \\u2013 Who We Are  \\n\\nCatharsis International is more than a recruitment agency; we are a bridge that connects ambition with opportunity. Our dedicated team of recruiters, compliance specialists, and client\\u2011success managers work tirelessly to match the right candidate with the right role, ensuring a seamless transition and long\\u2011term success for all parties involved. From initial assessment to post\\u2011placement support, we provide end\\u2011to\\u2011end service that stands out in a competitive market.\\n\\nExperience the Catharsis difference \\u2013 a legacy of trust, quality, and ethical recruitment that empowers careers and fuels business growth across borders.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 17:08:03', '2026-08-13 17:08:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('11', '11', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nEstablished 1997 \\u2013 Licensed RL\\u2011549 \\u2013 Recruiting with a Proven Record You Can Trust\\n\\nFounded in the bustling city of Dhaka in 1997, Catharsis International has grown into a premier manpower solutions provider, connecting skilled Bangladeshi talent with employers across Asia and the Gulf. Our long\\u2011standing reputation is built on transparency, reliability, and a commitment to excellence that employers and candidates alike can count on.\\n\\nWhy Choose Catharsis?\\n\\n* **Government\\u2011Approved Agency** \\u2013 We operate under the official Government License RL\\u2011549, ensuring full compliance with national recruitment regulations.\\n\\n* **ISO 9001:2015 Certified** \\u2013 Our processes are rigorously audited and continuously improved, guaranteeing the highest standards of quality management.\\n\\n* **BAIRA Member** \\u2013 As a proud member of the Bangladesh Association of International Recruitment Agencies, we adhere to industry best practices and ethical recruitment guidelines.\\n\\n* **Ethical Manpower Alliance** \\u2013 We partner with employers who value fairness, diversity, and long\\u2011term workforce development, fostering sustainable employment relationships.\\n\\nOur Legacy \\u2013 27+ Years of Excellence\\n\\nSince our inception, Catharsis International has consistently delivered top\\u2011quality talent across a diverse range of sectors, including hospitality, construction, healthcare, IT, and more. With over two decades of experience, we understand the unique needs of both employers and workers, and we tailor our solutions to meet those needs with precision and care.\\n\\nOur Story \\u2013 Who We Are\\n\\nCatharsis International is more than a recruitment agency; we are a bridge that connects ambition with opportunity. Our dedicated team of recruiters, compliance specialists, and client\\u2011success managers work tirelessly to match the right candidate with the right role, ensuring a seamless transition and long\\u2011term success for all parties involved. From initial assessment to post\\u2011placement support, we provide end\\u2011to\\u2011end service that stands out in a competitive market.\\n\\nExperience the Catharsis difference \\u2013 a legacy of trust, quality, and ethical recruitment that empowers careers and fuels business growth across borders.\"}', '{\"text\":\"ESTABLISHED 1997 \\u2013 LICENSE RL\\u2011549  \\nRecruiting with a Proven Record You Can Trust  \\n\\nFounded in the vibrant city of Dhaka in 1997, Catharsis International has evolved into a leading manpower solutions provider that bridges skilled Bangladeshi talent with employers across Asia and the Gulf. Our reputation is anchored in transparency, reliability, and a relentless pursuit of excellence\\u2014values that both candidates and businesses can count on.\\n\\nWHY CHOOSE CATHARSIS?  \\n\\n- **Government\\u2011Approved Agency** \\u2013 Operating under the official Government License RL\\u2011549 guarantees full compliance with national recruitment regulations and instills confidence in every placement.  \\n- **ISO 9001:2015 Certified** \\u2013 Our processes undergo rigorous audits and continuous improvement, ensuring the highest standards of quality management for both clients and candidates.  \\n- **BAIRA Member** \\u2013 As a proud member of the Bangladesh Association of International Recruitment Agencies, we adhere to industry best practices and uphold ethical recruitment guidelines.  \\n- **Ethical Manpower Alliance** \\u2013 We collaborate with employers who prioritize fairness, diversity, and long\\u2011term workforce development, fostering sustainable employment relationships that benefit all stakeholders.\\n\\nA LEGACY OF 27+ YEARS OF EXCELLENCE  \\n\\nWith over two decades of experience, Catharsis International consistently delivers top\\u2011quality talent across diverse sectors\\u2014including hospitality, construction, healthcare, IT, logistics, and manufacturing. Our deep understanding of each industry\'s unique demands allows us to tailor solutions that precisely match employer needs with candidate strengths, ensuring optimal fit and long\\u2011term success.\\n\\nOUR STORY \\u2013 WHO WE ARE  \\n\\nCatharsis International is more than a recruitment agency; we are a dynamic bridge that connects ambition with opportunity. Our dedicated team\\u2014comprising seasoned recruiters, compliance specialists, and client\\u2011success managers\\u2014works tirelessly to match the right candidate with the right role. From meticulous assessment and background verification to seamless onboarding and ongoing post\\u2011placement support, we deliver end\\u2011to\\u2011end service that stands out in a competitive market.\\n\\nEXPAND YOUR HORIZONS WITH CATHARSIS  \\n\\nWhether you are a multinational company seeking skilled professionals from Bangladesh or a local business looking to tap into a global talent pool, Catharsis International offers a comprehensive suite of services: talent acquisition, workforce planning, compliance management, and talent development programs. Our commitment to ethical recruitment, combined with our proven track record, empowers careers and fuels business growth across borders.\\n\\nExperience the Catharsis difference\\u2014an enduring legacy of trust, quality, and ethical recruitment that empowers careers and drives business success worldwide.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 17:11:03', '2026-08-13 17:11:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('12', '12', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Established 1997 \\u2022 License RL\\u2011549  \\nRecruiting with a Record \\u2013 You Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International has become the go\\u2011to partner for placing skilled Bangladeshi workers with employers across Asia and the Gulf. Operating under Government License RL\\u2011549, we proudly hold ISO\\u202f9001:2015 certification and are a member of BAIRA (Bangladesh Association of Industrial and Commercial Employers), underscoring our commitment to quality, transparency, and ethical recruitment practices.\\n\\nHome \\/ About Catharsis  \\n\\n**27+ Years of Legacy**  \\n- Established 1997  \\n- RL\\u2011549 Licensed  \\n- Government\\u2011Approved Agency  \\n- ISO\\u202f9001:2015 Certified Quality Management  \\n- BAIRA Member  \\n- Ethical Manpower Alliance  \\n\\n**Our Story \\u2013 Who We Are**  \\n\\nFrom a modest start in Dhaka to a leading manpower solutions provider, Catharsis has consistently delivered reliable, high\\u2011quality recruitment services for over two decades. We specialize in connecting Bangladeshi talent with opportunities in construction, hospitality, healthcare, manufacturing, and more, both within the region and in the Gulf countries. Our rigorous screening, comprehensive training, and ongoing support ensure that every placement meets the highest standards of performance and professionalism.\\n\\n**Key Credentials**  \\n- 1997 \\u2013 Founded in Dhaka, Bangladesh  \\n- RL\\u2011549 \\u2013 Government\\u2011licensed recruitment agency  \\n- ISO\\u202f9001:2015 \\u2013 Certified Quality Management System  \\n- BAIRA \\u2013 Member of Bangladesh\\u2019s premier employers\\u2019 association  \\n- Ethical Manpower Alliance \\u2013 Commitment to responsible recruitment  \\n\\n**Our Journey**  \\nCatharsis has grown by staying true to our core values: integrity, professionalism, and customer focus. We have helped thousands of families secure stable employment abroad while providing companies with a dependable talent pipeline. Our team of recruitment specialists, HR consultants, and industry experts understands the unique challenges of the Bangladeshi workforce and the global job market.  \\n\\n**Mission**  \\nTo bridge the gap between opportunity and talent, ensuring mutual success for both workers and employers, and to maintain a record of excellence that clients can check and trust.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 17:14:03', '2026-08-13 17:14:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('13', '13', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Since 1997, Catharsis International has been the premier bridge between skilled Bangladeshi talent and leading employers across Asia and the Gulf. With a robust legacy of over 27 years, we operate under the Government of Bangladesh\\u2019s official license RL\\u2011549, ensuring full compliance, transparency, and trust for every placement.\\n\\nOur commitment to excellence is reflected in our ISO\\u202f9001:2015 certification, which guarantees a systematic, quality\\u2011driven recruitment process that meets global standards. As a proud member of the Bangladesh Association of Industrial and Industrial Relations (BAIRA), we uphold ethical recruitment practices and actively contribute to the development of the Bangladeshi workforce.\\n\\nFrom our headquarters in Dhaka, we specialize in placing highly skilled professionals\\u2014from hospitality, construction, and engineering to information technology and customer service\\u2014into top companies across the Middle East, Southeast Asia, and beyond. Our end\\u2011to\\u2011end services include comprehensive candidate sourcing, rigorous screening, visa and immigration support, pre\\u2011employment training, and post\\u2011placement follow\\u2011up, ensuring seamless transitions for both employers and employees.\\n\\nWith a network of over 10,000 vetted candidates and partnerships with more than 200 corporate clients, Catharsis International has built a reputation for reliability, speed, and cost\\u2011effective staffing solutions. We provide real\\u2011time tracking, regular performance reports, and a dedicated account manager for every placement, giving our clients complete visibility and peace of mind.\\n\\nCatharsis International stands for transparency, integrity, and measurable results. We invite employers to discover how our data\\u2011driven approach, local expertise, and global reach can accelerate their workforce growth and drive business success.\\n\\nDiscover our story: from a small recruitment office in 1997 to a nationwide agency recognized for quality and ethical standards, we have consistently delivered record\\u2011setting recruitment outcomes.  \\n\\nWho we are: a dedicated team of recruitment specialists, immigration experts, and HR consultants committed to connecting Bangladeshi talent with opportunities that shape careers and industries.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 17:17:03', '2026-08-13 17:17:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('14', '14', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Established in 1997, Catharsis International has grown from a modest recruitment firm in Dhaka into a leading global manpower agency, connecting skilled Bangladeshi workers with employers across Asia and the Gulf. Our mission is simple: to provide reliable, ethical, and high\\u2011quality placement solutions that benefit both talent and industry partners.\\n\\nWith a proud legacy of more than 27 years, we are fully licensed by the Government of Bangladesh (RL\\u2011549) and recognized as a government\\u2011approved agency. Our commitment to excellence is further validated by ISO\\u202f9001:2015 certification, which ensures that every process\\u2014from candidate screening to contract finalization\\u2014meets the highest international standards of quality management. As a proud member of the Bangladesh Association of International Recruitment Agencies (BAIRA), we adhere to stringent ethical practices and professional guidelines.\\n\\nCatharsis International offers a comprehensive suite of services tailored to the unique needs of Bangladeshi workers and overseas employers. We specialize in placing professionals in key sectors such as manufacturing, construction, hospitality, and information technology, ensuring that every candidate receives thorough pre\\u2011employment training, health checks, and visa assistance. Our end\\u2011to\\u2011end support includes continuous monitoring, performance feedback, and post\\u2011placement follow\\u2011up, guaranteeing a seamless transition for both worker and employer.\\n\\nOur reputation for \\u201cRecruiting with a Record\\u201d is built on transparency and accountability. Every placement is backed by verifiable data, and our clients can check our track record through publicly available performance reports. By choosing Catharsis International, you\\u2019re not only accessing a vast pool of qualified talent but also partnering with a trusted agency that prioritizes compliance, worker welfare, and mutual success.\\n\\nWe are dedicated to continuous improvement and innovation. Our quality management system is regularly audited, and we invest in training our recruiters to stay ahead of industry trends and regulatory changes. This proactive approach ensures that our clients receive the most up\\u2011to\\u2011date solutions and that our workers are equipped for long\\u2011term success abroad.\\n\\nIf you\\u2019re looking for a dependable partner to navigate the complexities of international recruitment, look no further than Catharsis International. Contact us today to discover how our experience, certifications, and ethical framework can help you build a stronger, more diverse workforce.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 17:20:03', '2026-08-13 17:20:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('15', '15', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Catharsis International \\u2013 Your Gateway to Global Employment  \\nFounded in Dhaka in 1997, Catharsis International has become a trusted bridge between highly skilled Bangladeshi workers and leading employers across Asia and the Gulf. With a robust network, we match talent to opportunity, ensuring seamless placement and long\\u2011term career success.\\n\\nLicensed, Certified, Trusted  \\nOur agency operates under the official Government of Bangladesh license RL\\u2011549, guaranteeing full regulatory compliance. We are proud holders of the ISO\\u202f9001:2015 certification, which attests to our rigorous quality management system, and a valued member of the Bangladesh Association of International Recruitment Agencies (BAIRA). These credentials underscore our commitment to professionalism, transparency, and excellence.\\n\\nOver 27 Years of Proven Excellence  \\nWith more than two decades of experience, Catharsis International has cultivated a legacy of reliability and results. Our seasoned team has facilitated thousands of successful placements, earning us a reputation as a leading recruitment partner in the region. Every placement is backed by our proven processes and deep industry insight.\\n\\nComprehensive Recruitment Services  \\nWe offer end\\u2011to\\u2011end recruitment solutions: from talent sourcing and vetting to visa processing and onboarding support. Our services include industry\\u2011specific placement (engineering, hospitality, healthcare, IT, and more), pre\\u2011departure training, compliance management, and continuous post\\u2011placement follow\\u2011up. Whether you\\u2019re a job seeker or an employer, we tailor our approach to meet your unique needs.\\n\\nWhy Choose Catharsis International?  \\n* Transparent, data\\u2011driven selection process  \\n* Dedicated account managers for personalized support  \\n* 24\\/7 communication and real\\u2011time updates  \\n* Competitive fee structure with no hidden costs  \\n* Strong focus on worker welfare and ethical recruitment practices  \\n\\nEthical Manpower Alliance  \\nAs a member of the Ethical Manpower Alliance, we adhere to the highest standards of ethical recruitment. Our policies protect workers\\u2019 rights, promote fair wages, and ensure safe working conditions, fostering sustainable career paths for our candidates.\\n\\nOur Story \\u2013 Who We Are  \\nCatharsis International began as a small, mission\\u2011driven agency in 1997, driven by the vision to empower Bangladeshi talent on the global stage. Today, we stand as a pillar of trust and opportunity, continually expanding our reach and enhancing our services to meet the evolving demands of the international job market. Whether you\\u2019re seeking new horizons or looking to hire top talent, Catharsis International is your partner for success.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 17:23:03', '2026-08-13 17:23:03');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('16', '16', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Established in 1997 with Government License RL\\u2011549, Catharsis International has grown into a premier provider of skilled Bangladeshi manpower solutions across Asia and the Gulf. For more than 27 years we have matched talented workers with reputable employers, ensuring seamless placements that benefit both parties. Our reputation for reliability and excellence is underscored by our ISO\\u202f9001:2015 certification, which guarantees that every step of our recruitment process meets the highest quality management standards, and our membership in the BAIRA Ethical Manpower Alliance, a testament to our commitment to fair and transparent practices.\\n\\nRecruiting with a Record  \\nAt Catharsis, we pride ourselves on a proven track record of successful placements and long\\u2011term partnerships. From entry\\u2011level technicians to senior professionals, our candidates are rigorously vetted, trained, and ready to contribute immediately. We leverage a deep understanding of local labor markets, industry trends, and regulatory requirements to secure the best opportunities for our workers while meeting the exact needs of our clients.\\n\\nYou Can Check & Trust  \\nTransparency is at the heart of everything we do. Our licensing, ISO certification, and BAIRA membership are publicly verifiable credentials that give employers and workers alike the confidence to engage with us. Every candidate\\u2019s background, qualifications, and work history are meticulously documented, and our compliance with national and international labor laws ensures that all placements are fully legitimate and ethically sourced.\\n\\n27+ Years Legacy  \\n- 27+ Years of Industry Experience  \\n- RL\\u2011549 Licensed Government Agency  \\n- ISO\\u202f9001:2015 Certified Quality Management System  \\n- BAIRA Member of the Ethical Manpower Alliance  \\n\\nOur Story  \\nFounded in Dhaka in 1997, Catharsis International began as a small recruitment agency with a bold vision: to connect Bangladeshi talent with global opportunities while upholding the highest standards of integrity and professionalism. Over the decades, we expanded our reach, built a robust network of employers across the Gulf Cooperation Council, South Asia, and beyond, and refined our processes to become a trusted partner for both workers and businesses. Today, we continue to innovate, embracing digital tools, data analytics, and industry partnerships to stay ahead of market demands.\\n\\nWho We Are  \\nWe are a dedicated team of recruitment specialists, compliance experts, and client service professionals who share a common mission: to empower skilled workers and provide employers with the talent they need to thrive. Our services encompass full\\u2011cycle recruitment, pre\\u2011employment screening, visa and documentation assistance, onboarding support, and post\\u2011placement follow\\u2011up. By combining local expertise with global best practices, we deliver solutions that are tailored, efficient, and compliant with all regulatory requirements.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-13 17:26:03', '2026-08-13 17:26:03');
