INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('36', '36', '{\"text\":\"[h1] Recruiting with a Record \\r\\n\\r\\n          You Can Check &amp; Trust\\n\\n[p] Founded in 1997 in Dhaka, Catharsis International has built a 27\\u2011year legacy of placing skilled Bangladeshi workers with leading employers across Asia and the Gulf. We operate under Government License\\n\\n[p] Catharsis International excels in sourcing and mobilising a diverse range of professionals \\u2014 skilled, semi-skilled and unskilled workers. With a strategic focus on meeting specific requirements of overseas employers, Catharsis stands out with its extensive testing facilities and efficient mobilisation processes.\\n\\n[p] The agency boasts dedicated infrastructure including its own training centre, medical facilities and travel agency. This integrated approach has established Catharsis as a premier one-stop service provider in international manpower recruitment.\\n\\n[p] Corporate Identity\\n\\n[h2] Mission &amp; Vision\\n\\n[p] Our guiding principles drive ethical recruitment practices and uphold global standards.\\n\\n[p] We intend to create value of our business through satisfying our associates and partners. We strive to help clients and partners to achieve their target and develop their objectives by providing specific recruitment solutions.\\n\\n[p] Catharsis Group aims to become the leading organisation committed to deliver sustainable excellence in business performance by focusing on the benefit of our stakeholders. We are devoted to ensure the satisfaction of our clients and to provide job seekers a healthy, safe and excellent working environment.\\n\\n[p] Strategic Vision\\n\\n[h2] What We Set Out To Do\\n\\n[p] Being a reliable agency, Catharsis International works to serve overseas employers and Bangladeshi talent with maximum transparency. Our goal is to set the gold standard as Bangladesh\'s most trusted and ethical manpower recruitment partner.\\n\\n[p] Executive Leadership\\n\\n[h2] Leadership &amp; Governance\\n\\n[p] Guided by certified ethical leadership and rigorous international quality standards.\"}', '{\"text\":\"Founded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with top employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-16 12:59:46', '2026-08-16 13:49:20');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('37', '37', '{\"text\":\"Established 1997 \\u00b7 License RL-549\\n\\nRecruiting with a Record\\n\\nYou Can Check & Trust\\n\\nFounded in 1997 in Dhaka, Catharsis International has cultivated a 27\\u2011year legacy of deploying skilled Bangladeshi workers to top employers throughout Asia and the Gulf. We operate under a Government License.\\n\\nHome \\/ About Catharsis\\n\\n27+ Years Legacy\\n\\nEstablished 1997\\n\\nRL-549 Licensed\\n\\nGovt. Approved Agency\\n\\nISO 9001:2015\\n\\nCertified Quality Management\\n\\nBAIRA Member\\n\\nEthical Manpower Alliance\\n\\nOur Story\\n\\nWho We Are\"}', '{\"text\":\"Founded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with top employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-16 13:32:31', '2026-08-16 13:32:31');
INSERT INTO `rewrite_results` (`id`, `rewrite_job_id`, `original_segments`, `rewritten_segments`, `diff_data`, `original_html_hash`, `rewritten_html_hash`, `ai_request_tokens`, `ai_response_tokens`, `ai_duration_ms`, `created_at`, `updated_at`) VALUES ('38', '38', '{\"text\":\"[h1] Recruiting with Proven Record You Can Verify & Trust\\n\\n[p] Founded in 1997 in Dhaka, Catharsis International has cultivated a 27\\u2011year legacy of deploying skilled Bangladeshi workers to top employers throughout Asia and the Gulf, all under a Government License.\\n\\n[p] Catharsis International excels at sourcing and mobilizing a wide spectrum of professionals\\u2014skilled, semi\\u2011skilled, and unskilled. By aligning closely with overseas employers\\u2019 requirements, we distinguish ourselves through extensive testing facilities and efficient mobilization, ensuring rapid deployment, top\\u2011tier quality assurance, and rigorous standards.\\n\\n[p] The agency boasts dedicated infrastructure\\u2014its own training centre, medical facilities, and travel agency\\u2014positioning Catharsis as a globally trusted one\\u2011stop provider for international manpower recruitment across the region worldwide for Asia and the Gulf.\\n\\n[h2] Mission & Vision\\n\\n[p] Our guiding principles steer ethical recruitment and uphold global standards worldwide.\\n\\n[p] Our goal is to generate business value by delighting associates and partners. We tirelessly support clients and partners in achieving their objectives, delivering customized recruitment solutions that drive long\\u2011term success and foster sustainable growth globally.\\n\\n[p] Catharsis Group aims to lead as the premier organization delivering sustainable business excellence, centered on stakeholder benefit. We are dedicated to ensuring client satisfaction and providing job seekers with a healthy, safe, and exceptional workplace that nurtures growth and innovation worldwide, while offering continuous professional development opportunities globally.\\n\\n[p] Vision Strategy\\n\\n[h2] Our Goals, Commitments, Vision for Success\\n\\n[p] As a reliable agency, Catharsis International serves overseas employers and Bangladeshi talent with full transparency. Our ambition is to set the gold standard as Bangladesh\\u2019s most trusted and ethical manpower recruitment partner worldwide globally.\\n\\n[p] Leadership Group\\n\\n[h2] Leadership & Governance\\n\\n[p] Guided by certified ethical leadership and stringent global quality standards.\\n\\n[h3] Mr. Mohammed Ruhul Amin\"}', '{\"text\":\"Founded in 1997 in Dhaka, Catharsis International places Bangladeshi workers with top employers across Asia and the Gulf \\u2014 under Govt. License RL.-549, ISO 9001:2015 certification and BAIRA membership.\"}', NULL, NULL, NULL, NULL, NULL, '1120', '2026-08-16 13:39:37', '2026-08-16 13:39:37');
